using System;using System.IO;using System.Linq;using System.Globalization;using System.Threading.Tasks;
namespace NativeVideo {
 public static class ExportCli {
  public static async Task Run(){if(App.Arg("--project")==""||App.Arg("--out")=="")throw new ArgumentException("需要指定 --project 工程目录和 --out 输出文件");string project=Files.Full(App.Arg("--project")),output=Files.Full(App.Arg("--out")),work=Files.Full(App.Arg("--work-dir",output+".native-work"));var settings=Settings.Validate(J.O("width",double.Parse(App.Arg("--width","1920"),CultureInfo.InvariantCulture),"height",double.Parse(App.Arg("--height","1080"),CultureInfo.InvariantCulture),"fps",double.Parse(App.Arg("--fps","30"),CultureInfo.InvariantCulture),"workers",double.Parse(App.Arg("--workers","4"),CultureInfo.InvariantCulture),"mode",App.Arg("--mode","auto"),"bgmBaseMode",App.Arg("--bgm-base","auto"),"holdSeconds",double.Parse(App.Arg("--hold","1"),CultureInfo.InvariantCulture),"textSpeed",double.Parse(App.Arg("--text-speed","50"),CultureInfo.InvariantCulture),"autoSpeed",double.Parse(App.Arg("--auto-speed","50"),CultureInfo.InvariantCulture),"engine",App.Arg("--engine","webgal"),"gpu",App.Arg("--gpu","auto")));if(Files.Within(project,work,true))throw new IOException("工作目录必须位于工程之外");string scene=App.Arg("--scene","start.txt"),source=Files.Under(Path.Combine(project,"game/scene"),scene);if(!File.Exists(source))throw new FileNotFoundException("场景文件不存在",source);Directory.CreateDirectory(work);string snapshot=Path.Combine(work,"source-at-queue.txt");bool retry=App.Arg("--retry")=="true";if(!retry||!File.Exists(snapshot))File.Copy(source,snapshot,true);var bgm=App.Args.Select((a,i)=>new{a,i}).Where(x=>x.a=="--bgm"&&x.i+1<App.Args.Length).Select(x=>(object)Files.Full(App.Args[x.i+1])).ToArray();var request=J.O("project",project,"scene",scene,"sourceSnapshot",snapshot,"output",output,"jobDir",work,"settings",settings,"bgmFiles",bgm,"retry",retry,"mygoRoot",App.Arg("--mygo-root"));request["analysisOnly"]=App.Arg("--analyze")=="true";if(App.Arg("--start-line")!="")request["range"]=VideoWorkflow.ValidateRange(J.O("startLine",int.Parse(App.Arg("--start-line")),"endLine",int.Parse(App.Arg("--end-line"))),File.ReadAllText(snapshot));if(App.Arg("--music-timeline")=="true")request["musicTimeline"]=await VideoWorkflow.SnapshotMusic(project,work,true,scene);J.Write(Path.Combine(work,"request.json"),request);await new JobRunner(request).Run();Console.WriteLine(J.Text(J.Read(Path.Combine(work,"status.json"))));}
 }
}
